        <div class="hw-transfer"><span><b>${w("Step 2 — upload","Step 2 — push")}</b>${chip("git push")}</span><div class="hw-line out">${icon("east")}</div><div class="hw-line in">${icon("west")}</div><span><b>${w("Step 4 — get theirs","Step 4 — pull")}</b>${chip("git pull")}</span></div>
