    const place=(title,items,kind)=>`<section class="git-how-place ${kind}"><header>${icon(kind==="shared"?"cloud":"computer")}<strong>${title}</strong></header>${items.map((x,i)=>`<p><i>${i+1}</i><span><strong>${x[0]}</strong><small>${x[1]}</small></span></p>`).join("")}</section>`;
