  function normalizeFriendlyTerms(){if(S.technical||!S.body)return;const swaps=[["Use Git terms","Show Git terms"],["Show the real Git names","Show Git terms"],["These file changes only exist in this working folder.","You have unsaved changes."],["They have not been recorded as a version and have not been uploaded anywhere else.","They are only on this computer and have not been uploaded."],["They are recorded in the version history on this computer, but have not been uploaded anywhere else.","They are saved on this computer, but have not been uploaded."],["Recorded versions have been uploaded to the connected server. This does not guarantee a separate backup.","Your versions have been uploaded."],["Recorded versions exist only on this computer until you connect this project to somewhere else.","Your versions are saved on this computer. Connect this project when you want to upload them."],["One shared copy of the project that nobody edits directly. Everyone uploads versions here, and they join one shared history. It lets the team exchange work; it is not guaranteed to be a separate backup.","One shared copy of the project that nobody edits directly. Everyone uploads versions here, and they join one shared history."],["No. It remains only on this computer until uploaded, and an uploaded copy is not guaranteed to be a separate backup.","Saving keeps it on this computer. Upload it when you want a copy somewhere else."],["uploaded to the remote","uploaded"],["No textual preview for this file.","This file does not have a text preview."],["No versioned projects found","No projects with version history found"],["Recorded versions","Your versions"],["Upload to the team","Upload"],["Upload versions","Upload"],["Get teammates’ work","Download"],["Get team’s work","Download"],["Get the team’s work","Download"],["You have all your teammates’ work","Teammates’ work is up to date"],["Go back in time","Restore a version"],["Recording","Saving"],["recording","saving"],["Recorded","Saved"],["recorded","saved"],["Record","Save"],["record","save"]];for(const el of S.body.querySelectorAll("*"))for(const node of el.childNodes)if(node.nodeType===Node.TEXT_NODE){let value=node.nodeValue;for(const [from,to] of swaps)value=value.replaceAll(from,to);value=value.replace(/^(Share) (\d*) ?(version|versions)$/,"Upload $2 $3").replace(/(\d+) saved (version|versions) from your teammates/,"Teammates’ work · $1 new $2");node.nodeValue=value}}
