  function restoreFileScroll(){const list=S.body?.querySelector(".sp-files");if(list)list.scrollTop=S.filesScroll}
  function installGitHelpAction(){if(S.help||!S.body||S.body.querySelector(".git-content-help"))return;const bar=S.body.querySelector(".sp-repo-bar,.git-picker>header");if(!bar)return;const button=document.createElement("button");button.type="button";button.className="git-how git-content-help";button.dataset.gitHelp="";button.innerHTML=`${icon("help")}${S.technical?"How Git works":"How versions work"}`;const terms=bar.querySelector("[data-git-terms]");bar.insertBefore(button,terms||bar.lastElementChild)}
  function syncLanguage(){if(!S.root)return;const title=S.root.querySelector("[data-git-title]"),sub=S.root.querySelector("[data-git-subtitle]");if(title)title.textContent=S.help?(S.technical?"How Git works":"How folders and versions work"):(S.technical?"Git":"Versions");if(sub)sub.textContent=S.help?(S.technical?"working copies, commits and remotes":"a friendly guide to folders and saved versions"):(S.technical?"commits, branches, remotes and working tree":"save versions on this computer and upload them when ready");queueMicrotask(()=>{installGitHelpAction();finishRepoButton();finishFoldersPanel();removeFriendlyFolderHint();polishCleanState();polishHelpLanguage();finishCommitView();restoreFileScroll()})}
  function render(){if(!S.body)return;syncLanguage();if(S.help)return void(S.body.innerHTML=howItWorks());if(!S.path)return void(S.body.innerHTML=picker());if(!S.data){if(S.error)return void(S.body.innerHTML=`<div class="git-empty error">${icon("error")}<h2>${S.technical?"Could not open repository":"Could not open this project’s version history"}</h2><p>${esc(S.error)}</p><button data-git-choose>${S.technical?"Choose another repository":"Choose another project"}</button></div>`);return void(S.body.innerHTML=`<div class="git-empty">${icon("progress_activity")}<h2>${S.technical?"Opening repository":"Opening version history"}…</h2><p>${S.technical?"Reading status, diff and log.":"Your project is open. Its versions and file changes are loading now."}</p></div>`)}S.body.innerHTML=workspace()}
  function click(e){const pop=e.target.closest("[data-popout-tool]");if(pop)return window.wintShell?.popOutTool?.("git");const pin=e.target.closest("[data-pin-tool]");if(pin)return window.wintShell?.toggleToolPin?.("git");const go=e.target.closest("[data-open-tool]");if(go)return window.wintShell?.openTool?.(go.dataset.openTool);if(e.target.closest("[data-git-terms]")){S.technical=!S.technical;remember();render();return}const pick=e.target.closest("[data-git-open]");if(pick)return open(pick.dataset.gitOpen,pick.dataset.gitName);if(e.target.closest("[data-git-choose]"))return open("","");const resolve=e.target.closest("[data-git-resolve]");if(resolve&&S.selected){const mine=resolve.dataset.gitResolve==="mine",label=mine?(S.technical?"our version":"your version"):"their version";if(confirm(`Keep ${label} for this entire file? The other version will be replaced.`))return act(mine?"keep_mine":"keep_theirs",S.selected)}const skip=e.target.closest("[data-git-skip]");if(skip){const p=skip.dataset.gitSkip;S.excluded.has(p)?S.excluded.delete(p):S.excluded.add(p);render();return}const file=e.target.closest("[data-git-file]");if(file){S.selected=file.dataset.gitFile;render();return}const action=e.target.closest("[data-git-act]");if(action)return act(action.dataset.gitAct);if(e.target.closest("[data-git-discard-all]")&&confirm(S.technical?"Discard all unstaged tracked changes? This cannot be undone.":"Undo every file change shown here? This cannot be undone."))return act("discard_all");const point=e.target.closest("[data-git-point]");if(point){S.openPoint=S.openPoint===point.dataset.gitPoint?"":point.dataset.gitPoint;render();return}const see=e.target.closest("[data-git-see]");if(see){S.notice=`${S.technical?"Commit":"Saved version"} ${see.dataset.gitSee} — ${S.data.history.find(c=>c.hash===see.dataset.gitSee)?.subject||""}`;render();return}const restore=e.target.closest("[data-git-restore]");if(restore&&confirm(S.technical?"Hard reset to this commit? Current tracked changes will be discarded.":"Restore this earlier version? Your current file changes will be undone."))act("restore",restore.dataset.gitRestore)}
